socket.on('message', (msg, rinfo) => {
 // Parse the RTP packet header
 const version = (msg[0] & 0xC0) >> 6;
 const padding = (msg[0] & 0x20) >> 5;
 const extension = (msg[0] & 0x10) >> 4;
 const cc = msg[0] & 0x0F;
 const marker = (msg[1] & 0x80) >> 7;
 const pt = msg[1] & 0x7F;
 const seq = msg.readUInt16BE(2);
 const timestamp = msg.readUInt32BE(4);
 const ssrc = msg.readUInt32BE(8);

 // Log the RTP timestamp
 console.log(`RTP timestamp: ${timestamp}`);

 // Check if the packet contains header extensions
 if (extension === 1) {
 // Extract the extension data
 const extensionLengthFieldOffset = 4 + (cc \* 4); // Offset of the extension length field in the RTP header
 const extensionBitMask = 0x10; // Mask for the extension bit

 if ((msg[0] & extensionBitMask) !== 0) {
