 @type reg\_type: str
 """
 if reg\_type == Registration.PUB:
 rmap = self.pubs
 elif reg\_type == Registration.SUB:
 rmap = self.subs
 else:
 raise TypeError("invalid reg\_type: %s"%s)
 return rmap.get(resolved\_name, None)

 if reg\_type == Registration.PUB:
