int main(int argc, char \*argv[]) {
 if (argc != 4) {
 printf("Usage: %s \n", argv[0]);
 return 1;
 }

 int page\_table\_type = atoi(argv[1]);
 int address\_bits = atoi(argv[2]);
 int page\_size\_kb = atoi(argv[3]);

 if (page\_table\_type != 1 && page\_table\_type != 2) {
 printf("Error: Invalid page table type. Must be 1 or 2.\n");
 return 1;
 }

 if (address\_bits < 8 || address\_bits > 63) {
 printf("Error: Invalid address bits. Must be in the range [8..63].\n");
 return 1;
 }

 int valid\_page\_sizes[] = {1, 2, 4, 8, 16, 32, 64, 128, 256, 512};
 int valid\_page\_sizes\_count = sizeof(valid\_page\_sizes) / sizeof(valid\_page\_sizes[0]);
 int is\_valid\_page\_size = 0;

 for (int i = 0; i < valid\_page\_sizes\_count; i++) {
 if (page\_size\_kb == valid\_page\_sizes[i]) {
 is\_valid\_page\_size = 1;
 break;
 }
 }

 if (!is\_valid\_page\_size) {
 printf("Error: Invalid page size. Must be one of 1, 2, 4, 8, 16, 32, 64, 128, 256, 512.\n");
 return 1;
 }

 uint64\_t memory\_size = (uint64\_t)1 << address\_bits;
 uint64\_t page\_size = (uint64\_t)page\_size\_kb << 10;
 uint64\_t total\_pages = memory\_size / page\_size;

 if (memory\_size < page\_size) {
 printf("Error: Memory size is smaller than the page size.\n");
 return 1;
 }

 printf("Size of the memory: %" PRIu64 " bytes\n", memory\_size);
 printf("Total number of pages: %" PRIu64 "\n", total\_pages);

 int offset\_bits = (int)log2(page\_size);
 int vpn\_bits = address\_bits - offset\_bits;
 uint64\_t page\_table\_entries = (page\_table\_type == 1) ? total\_pages : (1 << vpn\_bits);

 printf("Total number of page table entries: %" PRIu64 "\n", page\_table\_entries);
 printf("Size of the page table: %" PRIu64 " bytes\n", page\_table\_entries \* sizeof(uint64\_t));
