Copy code
float morphBlendSDF(vec3 p, float d1, float d2, float blendFactor) {
 return mix(d1, d2, blendFactor);
}
Noise-Based Blending:
Blend two shapes using a 3D noise function to create organic and complex boundaries between them.
glsl
Copy code
float noiseBlendSDF(vec3 p, float d1, float d2, float noiseScale) {
 float noiseValue = (cnoise(p \* noiseScale) + 1.0) \* 0.5;
 return mix(d1, d2, noiseValue);
}
Directional Blend:
Create a blend between two shapes based on the direction of a specified axis. This can be useful for creating interesting patterns along a specific direction.
glsl
Copy code
float directionalBlendSDF(vec3 p, float d1, float d2, vec3 axis) {
 float axisValue = dot(p, normalize(axis));
 float blendFactor = smoothstep(-1.0, 1.0, axisValue);
 return mix(d1, d2, blendFactor);
}
Radial Blend:
Blend two shapes based on their distance from a given center point. This can be used to create interesting radial patterns and transitions.
glsl
Copy code
float radialBlendSDF(vec3 p, float d1, float d2, vec3 center, float radius) {
 float distanceFromCenter = length(p - center);
 float blendFactor = smoothstep(radius, radius \* 1.1, distanceFromCenter);
 return mix(d1, d2, blendFactor);
}
These are just a few ideas to get started. You can modify these techniques or combine them in various ways to create more complex and interesting SDF combinations. Feel free to iterate on these ideas, and I'm here to help with any questions or further suggestions.

#include "main.h"

/\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\* PRINT UNSIGNED NUMBER \*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*/
/\*\*
 \* print\_unsigned - Prints an unsigned number
 \* @types: List a of arguments
 \* @buffer: Buffer array to handle print
 \* @flags: Calculates active flags
 \* @width: get width
 \* @precision: Precision specification
 \* @size: Size specifier
 \* Return: Number of chars printed.
 \*/
int print\_unsigned(va\_list types, char buffer[],
 int flags, int width, int precision, int size)
{
 int i = BUFF\_SIZE - 2;
 unsigned long int num = va\_arg(types, unsigned long int);

 num = convert\_size\_unsgnd(num, size);

 if (num == 0)
 buffer[i--] = '0';

 buffer[BUFF\_SIZE - 1] = '\0';

 while (num > 0)
 {
 buffer[i--] = (num % 10) + '0';
 num /= 10;
 }

 i++;

 return (write\_unsgnd(0, i, buffer, flags, width, precision, size));
}

/\*\*\*\*\*\*\*\*\*\*\*\*\* PRINT UNSIGNED NUMBER IN OCTAL \*\*\*\*\*\*\*\*\*\*\*\*\*\*\*\*/
/\*\*
 \* print\_octal - Prints an unsigned number in octal notation
 \* @types: Lista of arguments
 \* @buffer: Buffer array to handle print
 \* @flags: Calculates active flags
 \* @width: get width
 \* @precision: Precision specification
 \* @size: Size specifier
 \* Return: Number of chars printed
 \*/
int print\_octal(va\_list types, char buffer[],
 int flags, int width, int precision, int size)
{

 int i = BUFF\_SIZE - 2;
 unsigned long int num = va\_arg(types, unsigned long int);
 unsigned long int init\_num = num;

 UNUSED(width);

 num = convert\_size\_unsgnd(num, size);

 if (num == 0)
 buffer[i--] = '0';

 buffer[BUFF\_SIZE - 1] = '\0';

 while (num > 0)
 {
 buffer[i--] = (num % 8) + '0';
 num /= 8;
 }

 if (flags & F\_HASH && init\_num != 0)
 buffer[i--] = '0';

 i++;

 return (write\_unsgnd(0, i, buffer, flags, width, precision, size));
}

/\*\*\*\*\*\*\*\*\*\*\*\*\*\* PRINT UNSIGNED NUMBER IN HEXADECIMAL \*\*\*\*\*\*\*\*\*\*\*\*\*\*/
/\*\*
 \* print\_hexadecimal - Prints an unsigned number in hexadecimal notation
 \* @types: Lista of arguments
 \* @buffer: Buffer array to handle print
 \* @flags: Calculates active flags
 \* @width: get width
 \* @precision: Precision specification
 \* @size: Size specifier
 \* Return: Number of chars printed
 \*/
int print\_hexadecimal(va\_list types, char buffer[],
 int flags, int width, int precision, int size)
{
 return (print\_hexa(types, "0123456789abcdef", buffer,
 flags, 'x', width, precision, size));
}

/\*\*\*\*\*\*\*\*\*\*\*\*\* PRINT UNSIGNED NUMBER IN UPPER HEXADECIMAL \*\*\*\*\*\*\*\*\*\*\*\*\*\*/
/\*\*
 \* print\_hexa\_upper - Prints an unsigned number in upper hexadecimal notation
 \* @types: Lista of arguments
 \* @buffer: Buffer array to handle print
 \* @flags: Calculates active flags
 \* @width: get width
 \* @precision: Precision specification
 \* @size: Size specifier
 \* Return: Number of chars printed
 \*/
int print\_hexa\_upper(va\_list types, char buffer[],
 int flags, int width, int precision, int size)
{
 return (print\_hexa(types, "0123456789ABCDEF", buffer,
 flags, 'X', width, precision, size));
}

/\*\*\*\*\*\*\*\*\*\*\*\*\*\* PRINT HEXX NUM IN LOWER OR UPPER \*\*\*\*\*\*\*\*\*\*\*\*\*\*/
/\*\*
 \* print\_hexa - Prints a hexadecimal number in lower or upper
 \* @types: Lista of arguments
 \* @map\_to: Array of values to map the number to
 \* @buffer: Buffer array to handle print
 \* @flags: Calculates active flags
 \* @flag\_ch: Calculates active flags
 \* @width: get width
 \* @precision: Precision specification
 \* @size: Size specifier
 \* @size: Size specification
 \* Return: Number of chars printed
 \*/
int print\_hexa(va\_list types, char map\_to[], char buffer[],
 int flags, char flag\_ch, int width, int precision, int size)
{
 int i = BUFF\_SIZE - 2;
 unsigned long int num = va\_arg(types, unsigned long int);
 unsigned long int init\_num = num;

 UNUSED(width);

 num = convert\_size\_unsgnd(num, size);

 if (num == 0)
 buffer[i--] = '0';

 buffer[BUFF\_SIZE - 1] = '\0';

 while (num > 0)
 {
 buffer[i--] = map\_to[num % 16];
 num /= 16;
 }

 if (flags & F\_HASH && init\_num != 0)
 {
 buffer[i--] = flag\_ch;
 buffer[i--] = '0';
 }

 i++;

 return (write\_unsgnd(0, i, buffer, flags, width, precision, size));
}

